bash: cat > /tmp/sparqltest/run.js <<'EOF'
const fs = require('fs');
const $rdf = require('rdflib');
const path = process.argv[2];
const qpath = process.argv[3] || '/app/solution.sparql';
const store = $rdf.graph();
$rdf.parse(fs.readFileSync(path,'utf8'), store, 'http://university.org/ontology/', 'text/turtle');
const query = $rdf.SPARQLToQuery(fs.readFileSync(qpath,'utf8'), false, store);
const res = [];
store.query(query, r => res.push(r), () => {}, {});
console.log('rows:', res.length);
for (const r of res) {
  const out = {};
  for (const k in r) { const t = r[k]; out[k] = t && t.value !== undefined ? t.value : String(t); }
  console.log(JSON.stringify(out));
}
EOF
cd /tmp/sparqltest && node run.js /app/university_graph.ttl 2>&1 | head -30

