store.load(fs.readFileSync('/app/university_graph.ttl','utf8'), {format:'text/turtle'});
const q = fs.readFileSync(process.argv[2]||'/app/solution.sparql','utf8');
const res = store.query(q);
const rows=[...res];
console.log('rows:', rows.length);
for (const r of rows) console.log(JSON.stringify(Object.fromEntries([...r].map(([k,v])=>[k, v.value]))));
EOF
